<script setup lang="ts">import {ref} from 'vue';import * as api from '../api/datasets';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const {data,error}=useResource(api.list,[]);const name=ref('新增巡护需求'),csv=ref(''),message=ref('');async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(file){if(file.size>1000000){message.value='CSV不能超过1MB';return}csv.value=await file.text()}}async function submit(){try{await api.create({name:name.value,csv_text:csv.value});message.value='';csv.value='';refreshResources()}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="02" title="需求点，先核对坐标" description="经纬度以十进制度输入，覆盖距离统一为千米；权重代表模拟巡护需求强度。"/><Notice :error="error||message"/><section class="paper table-scroll"><table><thead><tr><th>需求文件</th><th>样点数</th><th>总权重</th></tr></thead><tbody><tr v-for="d in data" :key="d.id"><td><b>{{d.name}}</b><small>{{d.source}}</small></td><td>{{d.row_count}}</td><td>{{d.total_weight}}</td></tr></tbody></table></section><form v-if="user?.role!=='viewer'" class="paper form-grid" @submit.prevent="submit"><h2>补充需求观测</h2><label>数据集名称<input v-model="name"/></label><label>CSV文件<input type="file" accept=".csv" @change="upload"/></label><label class="wide">观测内容<textarea v-model="csv" placeholder="site_id,label,latitude,longitude,weight"/></label><button class="primary">核查并导入需求</button></form></template>
